VIEW_SQL = ('\n                CREATE MATERIALIZED VIEW student_lo_scores AS\n                SELECT\n                    e.student_id,\n                    e.offering_id,\n                    lo.id AS learning_outcome_id,\n\n                    SUM(g.score / a.max_score * 100 * alw.weight)\n                    / SUM(alw.weight) AS score\n\n                FROM grading_enrollment e\n\n                JOIN grading_grade g\n                    ON g.enrollment_id = e.id\n\n                JOIN grading_assessment a\n                    ON a.id = g.assessment_id\n                    AND a.offering_id = e.offering_id\n                    AND a.max_score > 0\n\n                JOIN grading_assessmentloweight alw\n                    ON alw.assessment_id = a.id\n\n                JOIN grading_learningoutcome lo\n                    ON lo.id = alw.learning_outcome_id\n                    AND lo.offering_id = e.offering_id\n\n                GROUP BY\n                    e.student_id,\n                    e.offering_id,\n                    lo.id\n                HAVING SUM(alw.weight) > 0;\n            ', '\n                CREATE UNIQUE INDEX student_lo_scores_unique\n                ON student_lo_scores (\n                    student_id,\n                    offering_id,\n                    learning_outcome_id\n                );\n            ', '\n                CREATE MATERIALIZED VIEW course_po_scores AS\n                SELECT\n                    slo.student_id,\n                    slo.offering_id,\n                    pc.program_outcome_id,\n                    SUM(slo.score * lpw.weight)\n                    / NULLIF(SUM(lpw.weight),0) AS score\n                FROM student_lo_scores slo\n                JOIN grading_lopoweight lpw\n                    ON lpw.learning_outcome_id = slo.learning_outcome_id\n                JOIN grading_pocomponent pc\n                    ON pc.id = lpw.component_id\n                GROUP BY\n                    slo.student_id,\n                    slo.offering_id,\n                    pc.program_outcome_id\n                HAVING SUM(lpw.weight) > 0;\n            ', '\n                CREATE UNIQUE INDEX course_po_scores_unique\n                ON course_po_scores (\n                    student_id,\n                    offering_id,\n                    program_outcome_id\n                );\n            ', '\n                CREATE MATERIALIZED VIEW cross_course_po_scores AS\n                -- Courses weighted by ECTS, decision 0004.\n                SELECT\n                    cpo.student_id,\n                    cpo.program_outcome_id,\n                    SUM(cpo.score * c.ects) / SUM(c.ects) AS score\n                FROM course_po_scores cpo\n                JOIN grading_courseoffering o ON o.id = cpo.offering_id\n                JOIN grading_course c ON c.id = o.course_id\n                GROUP BY\n                    cpo.student_id,\n                    cpo.program_outcome_id\n                HAVING SUM(c.ects) > 0;\n            ', '\n                CREATE UNIQUE INDEX cross_course_po_scores_unique\n                ON cross_course_po_scores (\n                    student_id,\n                    program_outcome_id\n                );\n            ')
import importlib

from django.db import migrations, models

TEST_DATABASE = 'aculator_sprint4_test'


def forwards(apps, schema_editor):
    conn = schema_editor.connection
    if conn.vendor != 'postgresql' :
        raise RuntimeError('Grade partitioning requires PostgreSQL')
    with conn.cursor() as c:
        # Serialize concurrent changes while copying and switching tables.
        c.execute('LOCK TABLE grading_grade, grading_enrollment, grading_assessment, grading_courseoffering IN ACCESS EXCLUSIVE MODE')
        c.execute('''
            DO $$ BEGIN
                IF EXISTS (SELECT 1 FROM grading_grade WHERE term_id IS NULL) THEN
                    RAISE EXCEPTION 'NULL grade term';
                END IF;
                IF EXISTS (
                    SELECT 1 FROM grading_grade g
                    JOIN grading_enrollment e ON e.id=g.enrollment_id
                    JOIN grading_assessment a ON a.id=g.assessment_id
                    JOIN grading_courseoffering co ON co.id=e.offering_id
                    WHERE g.term_id<>co.term_id OR a.offering_id<>e.offering_id
                ) THEN RAISE EXCEPTION 'Inconsistent grade offering/term'; END IF;
            END $$;
        ''')
        c.execute('''
            CREATE TABLE grading_grade_partitioned (
                id bigint GENERATED BY DEFAULT AS IDENTITY
                    (SEQUENCE NAME grading_grade_partitioned_id_seq),
                score numeric(6,2) NOT NULL,
                assessment_id bigint NOT NULL,
                enrollment_id bigint NOT NULL,
                status varchar(10) NOT NULL,
                term_id bigint NOT NULL,
                CONSTRAINT grade_part_pk PRIMARY KEY (id,term_id),
                CONSTRAINT grade_part_unique UNIQUE (enrollment_id,assessment_id,term_id),
                CONSTRAINT grade_part_score_nonnegative CHECK (score>=0),
                CONSTRAINT grade_part_status_valid CHECK (status IN ('graded','absent')),
                CONSTRAINT grade_part_absent_zero CHECK (status<>'absent' OR score=0),
                CONSTRAINT grade_part_enrollment_fk FOREIGN KEY (enrollment_id)
                    REFERENCES grading_enrollment(id) DEFERRABLE INITIALLY DEFERRED,
                CONSTRAINT grade_part_assessment_fk FOREIGN KEY (assessment_id)
                    REFERENCES grading_assessment(id) DEFERRABLE INITIALLY DEFERRED,
                CONSTRAINT grade_part_term_fk FOREIGN KEY (term_id)
                    REFERENCES grading_term(id) DEFERRABLE INITIALLY DEFERRED
            ) PARTITION BY LIST(term_id)
        ''')
        c.execute('''
            DO $$ DECLARE t record; BEGIN
                FOR t IN SELECT id FROM grading_term LOOP
                    EXECUTE format('CREATE TABLE %I PARTITION OF grading_grade_partitioned FOR VALUES IN (%L)',
                                   'grading_grade_part_'||t.id, t.id);
                END LOOP;
            END $$;
            CREATE TABLE grading_grade_part_default PARTITION OF grading_grade_partitioned DEFAULT;
        ''')
        c.execute('''
            INSERT INTO grading_grade_partitioned(id,score,assessment_id,enrollment_id,status,term_id)
            SELECT id,score,assessment_id,enrollment_id,status,term_id FROM grading_grade;
            DO $$ BEGIN
                IF (SELECT count(*) FROM grading_grade) <> (SELECT count(*) FROM grading_grade_partitioned)
                   OR EXISTS (SELECT * FROM grading_grade EXCEPT SELECT * FROM grading_grade_partitioned)
                   OR EXISTS (SELECT * FROM grading_grade_partitioned EXCEPT SELECT * FROM grading_grade)
                THEN RAISE EXCEPTION 'Grade copy verification failed'; END IF;
            END $$;
        ''')
        c.execute("SET CONSTRAINTS ALL IMMEDIATE")
        # Reserve all IDs globally; deleted IDs remain reserved (no reuse).
        c.execute('''
            CREATE TABLE grading_grade_id_registry(id bigint PRIMARY KEY);
            INSERT INTO grading_grade_id_registry(id) SELECT id FROM grading_grade;
            CREATE FUNCTION grade_register_id() RETURNS trigger LANGUAGE plpgsql AS $$
            BEGIN
                INSERT INTO grading_grade_id_registry(id) VALUES (NEW.id);
                RETURN NEW;
            END $$;
            CREATE TRIGGER grade_register_id_trigger BEFORE INSERT ON grading_grade_partitioned
            FOR EACH ROW EXECUTE FUNCTION grade_register_id();
            CREATE FUNCTION grade_guard_update() RETURNS trigger LANGUAGE plpgsql AS $$
            BEGIN
                IF NEW.id IS DISTINCT FROM OLD.id OR NEW.term_id IS DISTINCT FROM OLD.term_id THEN
                    RAISE EXCEPTION 'Grade id and term_id are immutable';
                END IF;
                RETURN NEW;
            END $$;
            CREATE TRIGGER grade_guard_update_trigger BEFORE UPDATE ON grading_grade_partitioned
            FOR EACH ROW EXECUTE FUNCTION grade_guard_update();
            CREATE FUNCTION grade_check_links() RETURNS trigger LANGUAGE plpgsql AS $$
            DECLARE eid bigint; aid bigint; tid bigint;
            BEGIN
                SELECT offering_id INTO eid FROM grading_enrollment WHERE id=NEW.enrollment_id FOR SHARE;
                SELECT offering_id INTO aid FROM grading_assessment WHERE id=NEW.assessment_id FOR SHARE;
                SELECT term_id INTO tid FROM grading_courseoffering WHERE id=eid FOR SHARE;
                IF eid IS NULL OR aid IS NULL OR tid IS NULL OR eid<>aid OR NEW.term_id<>tid THEN
                    RAISE EXCEPTION 'Grade term/offering mismatch';
                END IF;
                RETURN NEW;
            END $$;
            CREATE TRIGGER grade_check_links_trigger BEFORE INSERT OR UPDATE ON grading_grade_partitioned
            FOR EACH ROW EXECUTE FUNCTION grade_check_links();
            CREATE INDEX grade_part_id_idx ON grading_grade_partitioned(id);
            CREATE INDEX grade_part_enrollment_idx ON grading_grade_partitioned(enrollment_id);
            CREATE INDEX grade_part_assessment_idx ON grading_grade_partitioned(assessment_id);
        ''')
        c.execute('''
            SELECT setval('grading_grade_partitioned_id_seq',
                GREATEST(COALESCE((SELECT max(id) FROM grading_grade_partitioned),0),1),
                EXISTS(SELECT 1 FROM grading_grade_partitioned));
        ''')
        for view in ('cross_course_po_scores','course_po_scores','student_lo_scores'):
            c.execute(f'DROP MATERIALIZED VIEW {view}')
        c.execute('ALTER TABLE grading_grade RENAME TO grading_grade_before_partition')
        c.execute('DROP TABLE grading_grade_before_partition')
        c.execute('ALTER TABLE grading_grade_partitioned RENAME TO grading_grade')
        original = importlib.import_module("grading.migrations.0002_materialized_views")

        # Recreate student_lo_scores and its unique index.
        for operation in original.Migration.operations[:2]:
             c.execute(operation.sql)

        # Recreate course_po_scores using the POComponent schema.
        components = importlib.import_module("grading.migrations.0004_po_components")
        course_po_sql = components.CREATE_VIEWS.split(
             "CREATE MATERIALIZED VIEW cross_course_po_scores AS"
        )[0]
        c.execute(course_po_sql)

        # Recreate cross_course_po_scores using the updated offering ECTS logic.
        updated = importlib.import_module("grading.migrations.0008_use_offering_ects_in_po_view")
        c.execute(updated.CREATE_VIEW)
        for view in (
            "student_lo_scores",
            "course_po_scores",
            "cross_course_po_scores",
        ):
            c.execute(f"REFRESH MATERIALIZED VIEW {view}")
        # The trigger function already exists from migration 0010.
        # Attach the history trigger to the new partitioned Grade table.
        c.execute("""
        CREATE TRIGGER grading_grade_change_history
        AFTER INSERT OR UPDATE OR DELETE ON grading_grade
        FOR EACH ROW
        EXECUTE FUNCTION grading_record_grade_change();
        """)
        c.execute('''
            CREATE FUNCTION grade_guard_upstream() RETURNS trigger LANGUAGE plpgsql AS $$
            BEGIN
                IF TG_TABLE_NAME = 'grading_enrollment' THEN
                    IF NEW.offering_id IS DISTINCT FROM OLD.offering_id
                       AND EXISTS (
                           SELECT 1 FROM grading_grade
                           WHERE enrollment_id = OLD.id
                       ) THEN
                        RAISE EXCEPTION 'Cannot change offering for enrollment with grades';
                    END IF;

                ELSIF TG_TABLE_NAME = 'grading_assessment' THEN
                    IF NEW.offering_id IS DISTINCT FROM OLD.offering_id
                       AND EXISTS (
                           SELECT 1 FROM grading_grade
                           WHERE assessment_id = OLD.id
                       ) THEN
                        RAISE EXCEPTION 'Cannot change offering for assessment with grades';
                    END IF;

                ELSIF TG_TABLE_NAME = 'grading_courseoffering' THEN
                    IF NEW.term_id IS DISTINCT FROM OLD.term_id
                       AND EXISTS (
                           SELECT 1
                           FROM grading_enrollment e
                           JOIN grading_grade g ON g.enrollment_id = e.id
                           WHERE e.offering_id = OLD.id
                       ) THEN
                        RAISE EXCEPTION 'Cannot change term for offering with grades';
                    END IF;
                END IF;

                RETURN NEW;
            END $$;

            CREATE TRIGGER grade_guard_enrollment
                BEFORE UPDATE OF offering_id ON grading_enrollment
                FOR EACH ROW EXECUTE FUNCTION grade_guard_upstream();

            CREATE TRIGGER grade_guard_assessment
                BEFORE UPDATE OF offering_id ON grading_assessment
                FOR EACH ROW EXECUTE FUNCTION grade_guard_upstream();

            CREATE TRIGGER grade_guard_offering
                BEFORE UPDATE OF term_id ON grading_courseoffering
                FOR EACH ROW EXECUTE FUNCTION grade_guard_upstream();
        ''')


class Migration(migrations.Migration):
    dependencies = [('grading', '0011_partition_grades_by_term')]
    atomic = True
    operations = [
        migrations.RunPython(forwards),
    ]
